import { describe, expect, it } from "vitest";

import { hasOwnedHeader, headerLine, stamp } from "./header.ts";

const HASH = "# @generated by @workerstack/repo";
const SLASH = "// @generated by @workerstack/repo";
const HTML = "<!-- @generated by @workerstack/repo -->";
const LEGACY = [
  "# Generated by repo sync. Do not edit.",
  "// Generated by repo sync. Do not edit.",
  "<!-- Generated by repo sync. Do not edit. -->",
  "<!-- Generated by repo sync from references/INDEX.md. Do not edit. -->",
  "# Generated by emit-mcp-policy.ts from agents/mcp-policy.jsonc.",
  "<!-- Generated by lessons.ts. Do not hand-edit. -->",
];
const FIRST_LINE = [
  [".github/workflows/ci.yml", "name: CI\n", `${HASH}\nname: CI\n`],
  [".vscode/tasks.json", "{}\n", `${SLASH}\n{}\n`],
  ["README.md", "# Title\n", `${HTML}\n# Title\n`],
];
const UNTOUCHED = [
  ["frontmatter markdown", ".claude/agents/scout.md", "---\nname: scout\n---\nbody\n"],
  ["frontmatter in a file whose format takes a comment", "README.md", "---\ntitle: x\n---\n# Title\n"],
  ["strict JSON", ".claude/settings.json", "{}\n"],
  ["a block-managed file", ".gitignore", "node_modules/\n"],
  ["an unregistered path", "docs/notes.txt", "notes\n"],
];
const LOOSE = [
  ["another case", "# @GENERATED by @WorkerStack/Repo\n"],
  ["inner spacing", "//   @generated   by   @workerstack/repo\n"],
  ["a trailing space", `${HTML}  \n`],
  ["tight html comment", "<!--@generated by @workerstack/repo-->\n"],
  ["CRLF", `${HASH}\r\nbody\r\n`],
  ["a BOM", `﻿${HASH}\nbody\n`],
];
const NEAR_MISSES = [
  ["the header on line 3", `a\nb\n${HASH}\n`],
  ["the header on line 2 with no shebang", `a\n${HASH}\n`],
  ["a legacy line with extra text", "# Generated by repo sync. Do not edit. Mine now.\n"],
  ["a legacy line with a trailing space", "# Generated by repo sync. Do not edit. \n"],
  ["the token with no comment marker", "@generated by @workerstack/repo\n"],
  ["the token with extra text", `${HASH} and mine\n`],
  ["an html comment left open", "<!-- @generated by @workerstack/repo\n"],
  ["another generator's header", "# @generated by someone-else\n"],
  ["a shebang alone", "#!/bin/sh"],
  ["an empty file", ""],
];

describe("stamp where the header goes", () => {
  it.each(FIRST_LINE)("puts the %s header on line 1", (rel, content, stamped) => {
    expect(stamp(rel, content)).toBe(stamped);
  });

  it("puts the header on line 2 after a shebang", () => {
    expect(stamp(".githooks/pre-commit", "#!/bin/sh\nexit 0\n")).toBe(`#!/bin/sh\n${HASH}\nexit 0\n`);
  });

  it("keeps a BOM and CRLF line endings", () => {
    expect(stamp("bunfig.toml", "﻿[install]\r\nauto = 1\r\n")).toBe(`﻿${HASH}\r\n[install]\r\nauto = 1\r\n`);
  });

  it("stamps an empty file with the header alone", () => {
    expect(stamp("bunfig.toml", "")).toBe(`${HASH}\n`);
  });

  it.each(UNTOUCHED)("leaves %s untouched", (_what, rel, content) => {
    expect(stamp(rel, content)).toBe(content);
  });
});

describe("stamp over an existing header", () => {
  it.each(LEGACY)("replaces the legacy line %s, never doubling the header", (legacy) => {
    expect(stamp("bunfig.toml", `${legacy}\n[install]\n`)).toBe(`${HASH}\n[install]\n`);
  });

  it("replaces a legacy line after a shebang", () => {
    const legacy = "#!/bin/sh\n# Generated by repo sync. Do not edit.\nexit 0\n";
    expect(stamp(".githooks/pre-push", legacy)).toBe(`#!/bin/sh\n${HASH}\nexit 0\n`);
  });

  it("is idempotent: a stamped file stamps to itself", () => {
    const once = stamp("README.md", "# Title\n");
    expect(stamp("README.md", once)).toBe(once);
  });

  it("rewrites a loose match of the new form to the exact line", () => {
    expect(stamp("bunfig.toml", "#  @Generated  BY @workerstack/repo \n[install]\n")).toBe(`${HASH}\n[install]\n`);
  });
});

describe("headerLine", () => {
  it("is line 1, or line 2 after a shebang", () => {
    expect(headerLine("a\nb\n")).toBe("a");
    expect(headerLine("#!/bin/sh\nb\n")).toBe("b");
  });

  it("drops a BOM and a CR", () => {
    expect(headerLine("﻿a\r\nb\r\n")).toBe("a");
  });

  it("is null for a shebang with no second line", () => {
    expect(headerLine("#!/bin/sh")).toBeNull();
  });
});

describe("hasOwnedHeader", () => {
  it.each([HASH, SLASH, HTML])("holds for %s on line 1", (header) => {
    expect(hasOwnedHeader(`${header}\nbody\n`)).toBe(true);
  });

  it("holds for the header on line 2 after a shebang", () => {
    expect(hasOwnedHeader(`#!/bin/sh\n${HASH}\nexit 0\n`)).toBe(true);
  });

  it.each(LEGACY)("holds for the legacy line %s", (legacy) => {
    expect(hasOwnedHeader(`${legacy}\nbody\n`)).toBe(true);
  });

  it.each(LOOSE)("holds loosely for %s", (_what, text) => {
    expect(hasOwnedHeader(text)).toBe(true);
  });

  it.each(NEAR_MISSES)("fails for %s", (_what, text) => {
    expect(hasOwnedHeader(text)).toBe(false);
  });
});
